import numpy as np
from scipy.optimize import curve_fit

D=[]
with open('graphene.dat') as f:
    for line in f:
        a,b=line.replace(',','.').split()
        D.append((float(a),float(b)))
D=np.array(sorted(D))
x=D[:,0]; y=D[:,1]

def lor(x,x0,gamma,amp,off):
    return off + amp*gamma**2/((x-x0)**2+gamma**2)

def lor_lin(x,x0,gamma,amp,a,b):
    return a + b*(x-x0) + amp*gamma**2/((x-x0)**2+gamma**2)

# fit G region with linear background
for lo,hi,name,p0 in [(16900,18100,'G',[17560,100,1000,18000,10]),
                      (15900,16900,'2D',[16450,80,1000,17000,0])]:
    m=(x>=lo)&(x<=hi)
    xx=x[m]; yy=y[m]
    try:
        if name=='G':
            popt,pcov=curve_fit(lor_lin,xx,yy,p0=p0,maxfev=100000)
            print(name,'linear',popt)
            print('rms',np.sqrt(np.mean((yy-lor_lin(xx,*popt))**2)))
        else:
            popt,pcov=curve_fit(lor,xx,yy,p0=p0,maxfev=100000)
            print(name,'const',popt)
            print('rms',np.sqrt(np.mean((yy-lor(xx,*popt))**2)))
    except Exception as e:
        print(name,'ERR',e)

# global 2 Lorentzians + linear background
m=(x>=15800)&(x<=18200)
xx=x[m]; yy=y[m]
def two_lor_lin(x,x01,g1,a1,x02,g2,a2,b0,b1):
    return b0 + b1*(x-17000) + a1*g1**2/((x-x01)**2+g1**2) + a2*g2**2/((x-x02)**2+g2**2)
p0=[16450,100,1000,17560,200,3000,17000,1]
try:
    popt,pcov=curve_fit(two_lor_lin,xx,yy,p0=p0,maxfev=200000)
    print('global',popt)
    print('rms',np.sqrt(np.mean((yy-two_lor_lin(xx,*popt))**2)))
except Exception as e:
    print('global ERR',e)
